require_once __DIR__ . '/../includes/init.php';requireLogin();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM items WHERE id=?');$s->execute([$id]);$item=$s->fetch();if(!$item){http_response_code(404);$title='Item not found';$active='items';layoutStart($title,$active);?><section class="panel"><h1>Item not found</h1><p>This item may have been removed.</p><a class="button light" href="<?= e(url('user/items.php')) ?>">Back to items</a></section><?php layoutEnd();exit;}$s=db()->prepare('SELECT sm.*,u.full_name FROM stock_movements sm JOIN users u ON u.id=sm.created_by WHERE sm.item_id=? ORDER BY sm.movement_date DESC,sm.id DESC LIMIT 20');$s->execute([$id]);$rows=$s->fetchAll();$title='Item details';$active='items';layoutStart($title,$active);
?><div class="page-heading"><div><div class="eyebrow">INVENTORY ITEM</div><h1><?= e($item['item_name']) ?></h1><p><?= e($item['item_code']) ?> · <?= e($item['category']) ?></p></div><a class="button light" href="<?= e(url(currentUser()['role']==='admin'?'admin/items.php':'user/items.php')) ?>">← Back to items</a></div><section class="detail-grid"><article class="panel item-overview"><div class="item-code-mark">#</div><span class="eyebrow">ITEM CODE</span><h2><?= e($item['item_code']) ?></h2><span class="badge <?= $item['quantity']<=$item['reorder_level']?'warning':'role-user' ?>"><?= $item['quantity']<=$item['reorder_level']?'Low stock':'In stock' ?></span></article><article class="panel detail-values"><div><span>Item name</span><b><?= e($item['item_name']) ?></b></div><div><span>Category</span><b><?= e($item['category']) ?></b></div><div><span>Location</span><b><?= e($item['location']) ?></b></div><div><span>Quantity</span><b><?= e($item['quantity'].' '.$item['unit']) ?></b></div><div><span>Reorder level</span><b><?= e($item['reorder_level'].' '.$item['unit']) ?></b></div><div><span>Created</span><b><?= e(dateValue($item['created_at'])) ?></b></div><div><span>Last updated</span><b><?= e(dateValue($item['updated_at'])) ?></b></div></article></section><section class="panel"><div class="panel-heading"><div><h2>Stock history</h2><p>Latest 20 movements for this item</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>IN</th><th>OUT</th><th>Reference</th><th>User</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty">No stock movement records for this item.</td></tr><?php else:foreach($rows as $r):?><tr><td><?= e(dateValue($r['movement_date'])) ?></td><td class="in-text"><?= $r['movement_type']==='IN'?'+'.e($r['quantity']):'—' ?></td><td class="out-text"><?= $r['movement_type']==='OUT'?'−'.e($r['quantity']):'—' ?></td><td><?= e($r['reference_note']?:'—') ?></td><td><?= e($r['full_name']) ?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php layoutEnd();?>
